-- Leave days of the year by employee. Output per row: staff|name|job|org|sick03|emergency09|type17|open. Posted (P) days only, open (O) apart. Types per CODES_MASTER 235.
SELECT x.s FROM (SELECT ROW_NUMBER() OVER (ORDER BY v.STAFF_ID) rn, v.STAFF_ID||'|'||TRIM(MAX(m.STAFF_NAME_1_S)||' '||MAX(m.STAFF_NAME_2_S)||' '||MAX(m.STAFF_NAME_F_S))||'|'||MAX(t.STAFF_JOB_ID)||'|'||MAX(t.ORGANIZATION_NO)||'|'||SUM(CASE WHEN v.VACATION_TYPE='03' AND v.POST_FLAG='P' THEN v.VACATION_NO_OF_DAY ELSE 0 END)||'|'||SUM(CASE WHEN v.VACATION_TYPE='09' AND v.POST_FLAG='P' THEN v.VACATION_NO_OF_DAY ELSE 0 END)||'|'||SUM(CASE WHEN v.VACATION_TYPE='17' AND v.POST_FLAG='P' THEN v.VACATION_NO_OF_DAY ELSE 0 END)||'|'||SUM(CASE WHEN v.POST_FLAG='O' THEN v.VACATION_NO_OF_DAY ELSE 0 END) s FROM {P}PS_STAFF_VACATIONS v JOIN {P}STAFF_MASTER m ON m.STAFF_ID=v.STAFF_ID LEFT JOIN {P}PS_STAFF_INTERNAL_TRANSFERS t ON t.STAFF_ID=v.STAFF_ID AND t.CURRENT_JOB='Y' WHERE v.DATE_FROM>=DATE '{LASTY}-01-01' AND v.DATE_FROM<=DATE '{LASTY}-12-31' AND v.POST_FLAG IN ('P','O') GROUP BY v.STAFF_ID) x WHERE x.rn BETWEEN 1 AND 200 ORDER BY x.rn
